using System.Reflection;
using System.Runtime.InteropServices;
using OcctSharp.CopiedCollections;
using OcctSharp.TransferRecords;
namespace OcctSharp.Runtime.Tests;
public sealed class TransferRecordsTests {
 static readonly int[] ResultCounts=[1,2];
 [Theory][InlineData(0)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]
 public void EveryNativeTopologyCastPreservesIdentity(int kind){using var box=ShapeFactory.CreateBox(2,3,4);using var compound=ShapeFactory.CreateCompound([box]);var parts=kind==0?new[]{compound}:box.GetSubShapes((ShapeKind)kind);try{Assert.NotEmpty(parts);using var set=OwnedShapeSet.Create(parts[0]);using var binder=TransferShapeBinder.Create(set);using var result=binder.GetShape(0,(ShapeKind)kind);Assert.True(result.IsEqual(parts[0]));}finally{foreach(var part in parts)part.Dispose();}}
 [Fact]public void CompSolidCastKeepsActualPartitionCarrier(){using var a=ShapeFactory.CreateBox(10,10,10);using var b=a.Transformed(ShapeTransform.CreateTranslation(5,0,0));using var plan=PartitionPlan.Create([a,b]);using var partition=plan.Build([new RegionProgram("containers",[new(RegionExpression.All,0)],false,true)]);using var output=partition.CopyOutput("containers");var parts=output.GetSubShapes(ShapeKind.CompSolid);try{Assert.Single(parts);using var set=OwnedShapeSet.Create(parts[0]);using var binder=TransferShapeBinder.Create(set);using var result=binder.GetShape(0,ShapeKind.CompSolid);Assert.True(result.IsEqual(parts[0]));}finally{foreach(var part in parts)part.Dispose();}}
 static void WithFile(Action<string> action){string path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".step");try{using(var box=ShapeFactory.CreateBox(2,3,4))ShapeExchange.WriteStep(box,path);action(path);}finally{File.Delete(path);}}
 [Theory][InlineData(ExchangeCollectionFormat.Step)][InlineData(ExchangeCollectionFormat.Iges)]
 public void PublicFileRecordsAndIndependentLifetime(ExchangeCollectionFormat format)=>OcctSharp.Tests.Shared.BatchAKTransferRecordsWorkflow.Run(format);
 [Fact]public void EmptyBinderAndNativeStatusRemainDistinctFromListCount(){using var empty=OwnedShapeSet.Create();using var binder=TransferShapeBinder.Create(empty);using var values=binder.Shapes;Assert.Equal(0,values.Count);Assert.False(binder.State.HasResult);using var box=ShapeFactory.CreateBox(1,1,1);using var appended=binder.Append(box);using var shapes=appended.Shapes;Assert.Equal(1,shapes.Count);Assert.False(appended.State.HasResult);Assert.Empty(binder.State.Messages);}
 [Fact]public void FunctionalEditsKeepOrderDuplicatesOrientationAndSource(){using var box=ShapeFactory.CreateBox(1,2,3);using var reverse=box.Reversed();using var moved=box.Transformed(ShapeTransform.CreateTranslation(5,0,0));using var source=OwnedShapeSet.Create(box,box);using var binder=TransferShapeBinder.Create(source);using var replaced=binder.Replace(1,reverse);using var appended=replaced.Append(moved);using var a=binder.GetShape(1);using var b=appended.GetShape(1);using var c=appended.GetShape(2);Assert.True(a.IsEqual(box));Assert.True(b.IsEqual(reverse));Assert.True(c.IsEqual(moved));source.Dispose();box.Dispose();reverse.Dispose();moved.Dispose();binder.Dispose();replaced.Dispose();appended.Dispose();Assert.True(a.IsValid);Assert.True(b.IsValid);Assert.True(c.IsValid);}
 [Fact]public void DiagnosticsAreCopiedAndEscapedWithoutSharingChecks(){using var empty=OwnedShapeSet.Create();using var binder=TransferShapeBinder.Create(empty);using var warn=binder.WithMessage("中文\n\t\"\\",true);using var fail=warn.WithMessage("é failure");Assert.Empty(binder.State.Messages);Assert.Single(warn.State.Messages);var state=fail.State;Assert.Equal(2,state.Messages.Count);Assert.Contains(state.Messages,m=>m.Warning && m.Text=="中文\n\t\"\\");Assert.Contains(state.Messages,m=>!m.Warning && m.Text=="é failure");fail.Dispose();Assert.Equal(2,state.Messages.Count);Assert.IsAssignableFrom<System.Collections.ObjectModel.ReadOnlyCollection<TransferMessage>>(state.Messages);}
 [Theory][InlineData(-1)][InlineData(1)][InlineData(int.MaxValue)]public void BinderIndicesAreValidated(int index){using var box=ShapeFactory.CreateBox(1,1,1);using var shapes=OwnedShapeSet.Create(box);using var binder=TransferShapeBinder.Create(shapes);Assert.Throws<ArgumentException>(()=>binder.GetShape(index));Assert.Throws<ArgumentException>(()=>binder.Replace(index,box));using var unchanged=binder.GetShape(0);Assert.True(unchanged.IsEqual(box));}
 [Theory][InlineData(-1)][InlineData(9)][InlineData(7)][InlineData(4)]public void TypedBinderRejectsWrongKinds(int kind){using var box=ShapeFactory.CreateBox(1,1,1);using var set=OwnedShapeSet.Create(box);using var binder=TransferShapeBinder.Create(set);Assert.Throws<ArgumentException>(()=>binder.GetShape(0,(ShapeKind)kind));using var solid=binder.GetShape(0,ShapeKind.Solid);Assert.True(solid.IsEqual(box));}
 [Fact]public void InvalidTextAndDisposedInputsAreRejected(){using var empty=OwnedShapeSet.Create();using var binder=TransferShapeBinder.Create(empty);Assert.Throws<ArgumentException>(()=>binder.WithMessage("bad\0message"));Assert.Throws<ArgumentException>(()=>TransferRecordSession.Read("bad\0path"));Assert.Throws<ArgumentException>(()=>TransferRecordSession.Read(Guid.NewGuid()+".step"));using var box=ShapeFactory.CreateBox(1,1,1);box.Dispose();Assert.Throws<ObjectDisposedException>(()=>binder.Append(box));binder.Dispose();Assert.Throws<ObjectDisposedException>(()=>binder.Shapes);}
 [Fact]public void ForeignAndDefaultNumbersDoNotConsumeEpoch()=>WithFile(path=>{using var a=TransferRecordSession.Read(path);using var b=TransferRecordSession.Read(path);Assert.Throws<ArgumentException>(()=>a.Transfer(b.ModelNumber(1)));Assert.Throws<ArgumentException>(()=>a.Transfer(default(TransferModelNumber)));Assert.Throws<ArgumentOutOfRangeException>(()=>a.Transfer());Assert.Throws<ArgumentOutOfRangeException>(()=>a.ModelNumber(0));Assert.Throws<ArgumentOutOfRangeException>(()=>a.ModelNumber(int.MaxValue));Assert.Throws<ArgumentException>(()=>a.Snapshot());using var result=a.TransferRoots();Assert.NotEmpty(result.Records);Assert.Throws<ArgumentException>(()=>a.TransferRoots());});
 [Fact]public void TransferIndicesAndModelNumbersRetainDifferentDomains()=>WithFile(path=>{using var a=TransferRecordSession.Read(path);using var b=TransferRecordSession.Read(path);using var sa=a.TransferRoots();using var sb=b.TransferRoots();Assert.Throws<ArgumentException>(()=>sa.GetEntity(sb.ModelNumber(1)));Assert.Throws<ArgumentException>(()=>sa.GetShape(sb.MapIndex(1)));Assert.Throws<ArgumentOutOfRangeException>(()=>sa.MapIndex(int.MaxValue));Assert.Throws<ArgumentException>(()=>sa.GetShape(default));Assert.Throws<ArgumentException>(()=>sa.GetEntity(default));Assert.All(sa.Roots,x=>Assert.InRange(x.Value,1,sa.Mappings.Count));Assert.All(sa.Complete,x=>Assert.InRange(x.Value,1,sa.Mappings.Count));});
 [Fact]public void ExplicitDuplicateRequestsKeepRecordsAndStatistics()=>WithFile(path=>{int number;using(var reference=TransferRecordSession.Read(path)){using var snapshot=reference.TransferRoots();number=snapshot.Records.First(x=>x.Recorded).ModelNumber.Value;}using var session=TransferRecordSession.Read(path);var entity=session.ModelNumber(number);using var result=session.Transfer(entity,entity);Assert.Equal(2,result.Records.Count);Assert.Equal(result.Records[0].ModelNumber,result.Records[1].ModelNumber);Assert.Equal(2,result.Statistics.Count);Assert.Equal(result.Statistics[0],result.Statistics[1]);Assert.All(result.Records,x=>{Assert.True(x.Recorded);Assert.Equal(ResultCounts,x.ResultCounts);Assert.Equal(2,x.Transferred.Count);});});
 [Fact]public void SingleNonTransferableEntityDoesNotMasqueradeAsShapeSuccess()=>WithFile(path=>{using var session=TransferRecordSession.Read(path);using var result=session.Transfer(session.ModelNumber(1));Assert.Equal(0,result.ShapeCount);Assert.Equal(0,result.TransferredCount);Assert.DoesNotContain(result.Mappings,x=>x.HasShape);Assert.Single(result.Records);Assert.NotNull(result.ProcessChecks);});
 [Fact]public void RepeatedSnapshotsFreezeDiagnosticsAndSurviveSessionDisposal()=>WithFile(path=>{using var session=TransferRecordSession.Read(path);using var first=session.TransferRoots();using var second=session.Snapshot();string before=System.Text.Json.JsonSerializer.Serialize(first.Records);Assert.Equal(before,System.Text.Json.JsonSerializer.Serialize(second.Records));session.Dispose();using var values=second.Shapes;Assert.True(values.Count>0);second.Dispose();Assert.Equal(before,System.Text.Json.JsonSerializer.Serialize(first.Records));Assert.Throws<ObjectDisposedException>(()=>second.Shapes);});
 [Fact]public void SnapshotDisposeRacesRetainCopiesOrThrowManagedDisposed()=>WithFile(path=>{using var session=TransferRecordSession.Read(path);using var first=session.TransferRoots();for(int attempt=0;attempt<30;++attempt){using var current=session.Snapshot();var errors=new System.Collections.Concurrent.ConcurrentQueue<Exception>();Parallel.For(0,10,i=>{try{if(i==0)current.Dispose();else{using var values=current.Shapes;Assert.True(values.Count>0);}}catch(ObjectDisposedException){}catch(Exception e){errors.Enqueue(e);}});Assert.Empty(errors);}});
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]unsafe delegate int TextRaw(nint token,byte* buffer,int capacity,out int length);
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate void ReleaseRaw(nint token,int kind);
 [UnmanagedFunctionPointer(CallingConvention.Cdecl)]unsafe delegate int RunRaw(nint token,int* numbers,int count,int roots,out nint result);
 static nint Token(object owner)=>((SafeHandle)owner.GetType().GetField("handle",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(owner)!).DangerousGetHandle();
 [Fact]public unsafe void RawWrongStaleTokensAndSmallBuffersFailWithoutPublishing()=>WithFile(path=>{using var session=TransferRecordSession.Read(path);using var snapshot=session.TransferRoots();nint library=NativeLibrary.Load(Path.Combine(AppContext.BaseDirectory,"occt","OcctSharp.Native.dll"));try{T Export<T>(string name)where T:Delegate=>Marshal.GetDelegateForFunctionPointer<T>(NativeLibrary.GetExport(library,name));var text=Export<TextRaw>("occtsharp_transfer_records_text");var release=Export<ReleaseRaw>("occtsharp_transfer_records_release");var run=Export<RunRaw>("occtsharp_transfer_records_run");nint token=Token(snapshot);Assert.Equal(0,text(token,null,0,out int n));Assert.True(n>1);byte sentinel=123;Assert.NotEqual(0,text(token,&sentinel,1,out n));Assert.Equal(123,sentinel);Assert.NotEqual(0,text(Token(session),null,0,out n));Assert.Equal(0,n);release(token,0);Assert.Equal(0,text(token,null,0,out n));Assert.NotEqual(0,run(Token(session),null,int.MaxValue,0,out nint result));Assert.Equal(0,result);snapshot.Dispose();Assert.NotEqual(0,text(token,null,0,out n));Assert.Equal(0,n);}finally{NativeLibrary.Free(library);}});
}
